import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val N = scanner.nextInt()
    val str = scanner.next()

    val parts = str.split("W")
    val output = mutableListOf<Int>()

    for (part in parts) {
        if (part.isNotEmpty()) {
            output.add(part.length)
        }
    }

    println(output.size)
    println(output.joinToString(" "))
}

